1	<?php
2	
3	namespace App\Providers\Filament;
4	
5	use Filament\Http\Middleware\Authenticate;
6	use Filament\Http\Middleware\AuthenticateSession;
7	use Filament\Http\Middleware\DisableBladeIconComponents;
8	use Filament\Http\Middleware\DispatchServingFilamentEvent;
9	use App\Filament\Pages\Dashboard;
10	use Filament\Panel;
11	use Filament\PanelProvider;
12	use Filament\Support\Colors\Color;
13	use Filament\Widgets;
14	use Illuminate\Cookie\Middleware\AddQueuedCookiesToResponse;
15	use Illuminate\Cookie\Middleware\EncryptCookies;
16	use Illuminate\Foundation\Http\Middleware\VerifyCsrfToken;
17	use Illuminate\Routing\Middleware\SubstituteBindings;
18	use Illuminate\Session\Middleware\StartSession;
19	use Illuminate\View\Middleware\ShareErrorsFromSession;
20	
21	class AdminPanelProvider extends PanelProvider
22	{
23	    public function panel(Panel $panel): Panel
24	    {
25	        return $panel
26	            ->default()
27	            ->id('admin')
28	            ->path('admin')
29	            ->login()
30	            ->passwordReset()
31	            ->colors([
32	                'primary' => Color::Amber,
33	            ])
34	            ->discoverResources(in: app_path('Filament/Resources'), for: 'App\\Filament\\Resources')
35	            ->discoverPages(in: app_path('Filament/Pages'), for: 'App\\Filament\\Pages')
36	            ->pages([
37	                Dashboard::class,
38	            ])
39	            ->discoverWidgets(in: app_path('Filament/Widgets'), for: 'App\\Filament\\Widgets')
40	            ->widgets([
41	                // Widgets\AccountWidget::class,
42	            ])
43	            ->middleware([
44	                EncryptCookies::class,
45	                AddQueuedCookiesToResponse::class,
46	                StartSession::class,
47	                AuthenticateSession::class,
48	                ShareErrorsFromSession::class,
49	                VerifyCsrfToken::class,
50	                SubstituteBindings::class,
51	                DisableBladeIconComponents::class,
52	                DispatchServingFilamentEvent::class,
53	            ])
54	            ->authMiddleware([
55	                Authenticate::class,
56	            ]);
57	    }
58	}
